{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.B2B_RECONCILIATION_RAW AS WITH dates AS ( SELECT DATE \'2026-08-01\' AS start_date, CONVERT_TIMEZONE( \'Asia/Kolkata\', CURRENT_TIMESTAMP() )::DATE AS end_date ), uc_sku AS ( SELECT CASE WHEN marketplace_mapped IN ( \'M-NOW\', \'M_NOW_WESTBENGAL\' ) THEN \'MYNTRA_NOW\' ELSE marketplace_mapped END AS marketplace_group, COALESCE( NULLIF(TRIM(order_name::STRING), \'\'), NULLIF(TRIM(invoice_code::STRING), \'\'), NULLIF(TRIM(awb::STRING), \'\') ) AS uc_order_ref, MIN(order_name) AS order_name, MIN(invoice_code) AS invoice_code, MIN(awb) AS awb, MIN(dispatched_timestamp) AS dispatched_timestamp, MIN(marketplace_mapped) AS marketplace_mapped, MIN(warehouse_name) AS warehouse_name, UPPER(TRIM(sku::STRING)) AS sku_key, COUNT(*)::NUMBER(38,0) AS uc_qty, ROUND( SUM(selling_price), 2 ) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 CROSS JOIN dates WHERE marketplace_mapped IN ( \'FLIPKART_SOR\', \'MYNTRA_SJIT\', \'M-NOW\', \'M_NOW_WESTBENGAL\', \'SLIKK\', \'KNOT\', \'ZILO\', \'INSTAMART\', \'NOON\' ) AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN dates.start_date AND dates.end_date AND NULLIF( TRIM(sku::STRING), \'\' ) IS NOT NULL AND UPPER(TRIM(sku::STRING)) <> \'DUMMY-BOX-01\' AND COALESCE( warehouse_name, \'\' ) NOT ILIKE \'%surat-VRMall%\' GROUP BY CASE WHEN marketplace_mapped IN ( \'M-NOW\', \'M_NOW_WESTBENGAL\' ) THEN \'MYNTRA_NOW\' ELSE marketplace_mapped END, COALESCE( NULLIF(TRIM(order_name::STRING), \'\'), NULLIF(TRIM(invoice_code::STRING), \'\'), NULLIF(TRIM(awb::STRING), \'\') ), UPPER(TRIM(sku::STRING)) ), uc_order AS ( SELECT marketplace_group, uc_order_ref, MIN(order_name) AS order_name, MIN(invoice_code) AS invoice_code, MIN(awb) AS awb, MIN(dispatched_timestamp) AS dispatched_timestamp, MIN(marketplace_mapped) AS marketplace_mapped, MIN(warehouse_name) AS warehouse_name, SUM(uc_qty)::NUMBER(38,0) AS uc_total_qty, COUNT(*)::NUMBER(38,0) AS uc_sku_count, ROUND( SUM(uc_value), 2 ) AS uc_total_value FROM uc_sku GROUP BY marketplace_group, uc_order_ref ), logic_base AS ( SELECT raw._airbyte_data, UPPER( COALESCE( raw._airbyte_data:\"Customer_Name\"::STRING, \'\' ) || \' | \' || COALESCE( raw._airbyte_data:\"Account_Name\"::STRING, \'\' ) ) AS party_text, COALESCE( NULLIF( TRIM( raw._airbyte_data:\"New_Bill_No\"::STRING ), \'\' ), NULLIF( TRIM( raw._airbyte_data:\"Order_No\"::STRING ), \'\' ), NULLIF( TRIM( raw._airbyte_data:\"Gr_Number\"::STRING ), \'\' ), MD5( TO_JSON(raw._airbyte_data) ) ) AS logic_invoice_ref FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE raw CROSS JOIN dates WHERE TRIM( raw._airbyte_data:\"Branch_Code\"::STRING ) IN (\'2\',\'8\',\'94\') AND TRY_TO_DATE( raw._airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) BETWEEN dates.start_date AND dates.end_date ), logic_filtered AS ( SELECT _airbyte_data, party_text, logic_invoice_ref, CASE WHEN party_text ILIKE \'%FLIPKART INDIA PRIVATE LIMITED%\' THEN \'FLIPKART_SOR\' WHEN party_text ILIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN party_text ILIKE \'%MYNTRA JABONG%\' OR party_text ILIKE \'%MNOW%\' OR party_text ILIKE \'%M-NOW%\' THEN \'MYNTRA_NOW\' WHEN party_text ILIKE \'%SPRINTPRO%\' OR party_text ILIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN party_text ILIKE \'%INSTAMART%\' OR party_text ILIKE \'%CLOUDKART%\' OR party_text ILIKE \'%CLOUDSTORE%\' OR party_text ILIKE \'%JUPITER KART%\' OR party_text ILIKE \'%MOKSH ENTERPRISES%\' THEN \'INSTAMART\' WHEN party_text ILIKE \'%BANDIDOS RETAIL LLC%\' THEN \'NOON\' WHEN party_text ILIKE \'%KNOT%\' THEN \'KNOT\' WHEN party_text ILIKE \'%ZILO%\' THEN \'ZILO\' ELSE NULL END AS marketplace_group FROM logic_base WHERE party_text ILIKE \'%FLIPKART INDIA PRIVATE LIMITED%\' OR party_text ILIKE \'%SJIT%\' OR party_text ILIKE \'%MYNTRA JABONG%\' OR party_text ILIKE \'%MNOW%\' OR party_text ILIKE \'%M-NOW%\' OR party_text ILIKE \'%SPRINTPRO%\' OR party_text ILIKE \'%SLIKK%\' OR party_text ILIKE \'%INSTAMART%\' OR party_text ILIKE \'%CLOUDKART%\' OR party_text ILIKE \'%CLOUDSTORE%\' OR party_text ILIKE \'%JUPITER KART%\' OR party_text ILIKE \'%MOKSH ENTERPRISES%\' OR party_text ILIKE \'%BANDIDOS RETAIL LLC%\' OR party_text ILIKE \'%KNOT%\' OR party_text ILIKE \'%ZILO%\' ), logic_sku AS ( SELECT logic.marketplace_group, logic.logic_invoice_ref, UPPER( TRIM( item.value:\"AddlItemCode\"::STRING ) ) AS sku_key, SUM( COALESCE( TRY_TO_NUMBER( item.value:\"Quantity\"::STRING ), 0 ) )::NUMBER(38,0) AS logic_qty FROM logic_filtered logic, LATERAL FLATTEN( INPUT => TRY_PARSE_JSON( logic._airbyte_data:\"LstItems\"::STRING ) ) item WHERE logic.marketplace_group IS NOT NULL AND NULLIF( TRIM( item.value:\"AddlItemCode\"::STRING ), \'\' ) IS NOT NULL GROUP BY logic.marketplace_group, logic.logic_invoice_ref, UPPER( TRIM( item.value:\"AddlItemCode\"::STRING ) ) ), logic_order AS ( SELECT marketplace_group, logic_invoice_ref, SUM(logic_qty)::NUMBER(38,0) AS logic_total_qty, COUNT(*)::NUMBER(38,0) AS logic_sku_count FROM logic_sku GROUP BY marketplace_group, logic_invoice_ref ), candidate AS ( SELECT uc.marketplace_group, uc.uc_order_ref, logic.logic_invoice_ref, uo.uc_total_qty, uo.uc_sku_count, lo.logic_total_qty, COUNT(*)::NUMBER(38,0) AS overlapping_skus, SUM( LEAST( uc.uc_qty, logic.logic_qty ) )::NUMBER(38,0) AS matched_qty FROM uc_sku uc JOIN logic_sku logic ON uc.marketplace_group = logic.marketplace_group AND uc.sku_key = logic.sku_key JOIN uc_order uo ON uc.marketplace_group = uo.marketplace_group AND uc.uc_order_ref = uo.uc_order_ref JOIN logic_order lo ON logic.marketplace_group = lo.marketplace_group AND logic.logic_invoice_ref = lo.logic_invoice_ref GROUP BY uc.marketplace_group, uc.uc_order_ref, logic.logic_invoice_ref, uo.uc_total_qty, uo.uc_sku_count, lo.logic_total_qty ), best_candidate AS ( SELECT *, matched_qty::FLOAT / NULLIF( uc_total_qty, 0 ) AS qty_coverage, overlapping_skus::FLOAT / NULLIF( uc_sku_count, 0 ) AS sku_coverage, ROW_NUMBER() OVER ( PARTITION BY marketplace_group, uc_order_ref ORDER BY matched_qty DESC, overlapping_skus DESC, ABS( uc_total_qty - logic_total_qty ) ASC, logic_invoice_ref ) AS rn FROM candidate ), selected_match AS ( SELECT marketplace_group, uc_order_ref, logic_invoice_ref, matched_qty, qty_coverage, sku_coverage FROM best_candidate WHERE rn = 1 AND ( qty_coverage >= 0.50 OR sku_coverage >= 0.50 ) ), invoice_missing AS ( SELECT \'INVOICE_MISSING\' AS reconciliation_status, uc.marketplace_group, uc.uc_order_ref AS batch_reference, uc.order_name, uc.invoice_code, uc.awb, uc.dispatched_timestamp, uc.marketplace_mapped, uc.warehouse_name, NULL::STRING AS sku, uc.uc_total_qty AS uc_quantity, 0::NUMBER AS logic_quantity, uc.uc_total_qty AS missing_quantity, uc.uc_sku_count AS distinct_sku_count, uc.uc_total_value AS missing_value, NULL::STRING AS matched_logic_invoice FROM uc_order uc LEFT JOIN selected_match matched ON uc.marketplace_group = matched.marketplace_group AND uc.uc_order_ref = matched.uc_order_ref WHERE matched.uc_order_ref IS NULL ), item_shortage_base AS ( SELECT uc.marketplace_group, uc.uc_order_ref, uc.order_name, uc.invoice_code, uc.awb, uc.dispatched_timestamp, uc.marketplace_mapped, uc.warehouse_name, uc.sku_key, uc.uc_qty, uc.uc_value, selected.logic_invoice_ref, COALESCE( logic.logic_qty, 0 )::NUMBER(38,0) AS logic_qty, GREATEST( uc.uc_qty - COALESCE( logic.logic_qty, 0 ), 0 )::NUMBER(38,0) AS missing_qty FROM uc_sku uc JOIN selected_match selected ON uc.marketplace_group = selected.marketplace_group AND uc.uc_order_ref = selected.uc_order_ref LEFT JOIN logic_sku logic ON selected.marketplace_group = logic.marketplace_group AND selected.logic_invoice_ref = logic.logic_invoice_ref AND uc.sku_key = logic.sku_key ), item_missing AS ( SELECT \'ITEM_MISSING\' AS reconciliation_status, marketplace_group, uc_order_ref AS batch_reference, order_name, invoice_code, awb, dispatched_timestamp, marketplace_mapped, warehouse_name, sku_key AS sku, uc_qty AS uc_quantity, logic_qty AS logic_quantity, missing_qty AS missing_quantity, 1::NUMBER AS distinct_sku_count, ROUND( CASE WHEN uc_qty > 0 THEN (uc_value / uc_qty) * missing_qty ELSE 0 END, 2 ) AS missing_value, logic_invoice_ref AS matched_logic_invoice FROM item_shortage_base WHERE missing_qty > 0 ), final_output AS ( SELECT * FROM invoice_missing UNION ALL SELECT * FROM item_missing ) SELECT dates.start_date AS reconciliation_from_date, dates.end_date AS reconciliation_to_date, output.reconciliation_status, output.marketplace_group, output.batch_reference, output.order_name, output.invoice_code, output.awb, output.dispatched_timestamp, output.marketplace_mapped, output.warehouse_name, output.sku, output.uc_quantity, output.logic_quantity, output.missing_quantity, output.distinct_sku_count, output.missing_value, output.matched_logic_invoice FROM final_output output CROSS JOIN dates ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            